// Shared helpers for the mock-data read tests.
// The mock files are generated by ..\generate_mock_data.py (output: ..\mock-datasets, gitignored).
// If a file is absent, TryOpen returns false and the caller skips the test so the suite stays green
// without the (generated) binary test data; run `python generate_mock_data.py` (repo root) to produce it.


using System;
using System.IO;
using NetcdfSharp.ucar.ma2;
using NetcdfSharp.ucar.nc2;

namespace NetcdfSharp.ucar.tests
{

	/// <summary>
	/// Locates the generated mock datasets and centralises the open/skip/read boilerplate
	/// shared by every mock-data test.
	/// </summary>
	public static class MockDataSupport
	{
		private static readonly string mockDataDir = FindMockDataDir();

		private static string FindMockDataDir()
		{
			string dir = AppContext.BaseDirectory;
			while (dir != null)
			{
				string candidate = Path.Combine(dir, "mock-datasets");
				if (Directory.Exists(candidate))
				{
					return candidate;
				}
				dir = Path.GetDirectoryName(dir);
			}
			return null;
		}

		/// <summary>
		/// true if the named mock file exists.
		/// </summary>
		public static bool HasData(string name)
		{
			return mockDataDir != null && File.Exists(Path.Combine(mockDataDir, name));
		}

		/// <summary>
		/// Absolute path of the named mock file (call only when <see cref="HasData"/> is true).
		/// </summary>
		public static string DataPath(string name)
		{
			return Path.Combine(mockDataDir, name);
		}

		/// <summary>
		/// Open the named mock file, or return null when the data is absent (test should skip).
		/// </summary>
		public static NetcdfFile TryOpen(string name)
		{
			return HasData(name) ? NetcdfFiles.open(DataPath(name)) : null;
		}

		/// <summary>
		/// Open the named mock file with an iosp message (eg IOSP_MESSAGE_ADD_RECORD_STRUCTURE),
		/// or return null when the data is absent (test should skip).
		/// </summary>
		public static NetcdfFile TryOpen(string name, object iospMessage)
		{
			return HasData(name) ? NetcdfFiles.open(DataPath(name), 0, null, iospMessage) : null;
		}

		/// <summary>
		/// Find a variable by full group path, falling back to the short name for readers
		/// that flatten groups (HDF5) or need an unescaped lookup.
		/// </summary>
		public static Variable FindVar(NetcdfFile nc, string fullName)
		{
			Variable v = nc.findVariable(fullName);
			if (v != null)
			{
				return v;
			}
			int slash = fullName.LastIndexOf('/');
			return slash >= 0 ? nc.findVariable(fullName.Substring(slash + 1)) : null;
		}

		/// <summary>
		/// Read the whole variable.
		/// </summary>
		public static NcArray readAll(NetcdfFile nc, Variable v)
		{
			Section full = Section.fill(null, v.Shape);
			return nc.readData(v, full);
		}

		/// <summary>
		/// Assert the variable exists, has the given data type and shape.
		/// </summary>
		public static Variable AssertVar(NetcdfFile nc, string name, DataType dtype, int[] shape)
		{
			Variable v = FindVar(nc, name);
			Xunit.Assert.NotNull(v);
			Xunit.Assert.Equal(dtype, v.DataType);
			Xunit.Assert.Equal(shape, v.Shape);
			return v;
		}
	}
}
